describe('Readonly object capture and deterministic accepted archive',()=>{
  it.each([['list',{Bucket:'foreign',MaxKeys:32}],['list',{Bucket:'archives',MaxKeys:32,Prefix:'backups/'}],['get',{Bucket:'archives',Key:'backups/x',IfMatch:'"'+'a'.repeat(32)+'"'}],['get',{Bucket:'media-source',Key:'../x',IfMatch:'"'+'a'.repeat(32)+'"'}],['head',{Bucket:'media-source',Key:'x',IfMatch:'*'}]])('refuses foreign or unbounded SDK request %s before dispatch',(kind,input)=>{expect(()=>assertD3CaptureS3Request(kind as 'list',input as never)).toThrow();});
  function prerequisiteFixture(){const authority={sourceProfileSha256:String(profile.source_profile_sha256),dataProfileSha256:String(profile.data_profile_sha256),capsuleProfileSha256:String(profile.capsule_profile_sha256),reservationProfileSha256:String(profile.reservation_profile_sha256),migrationFingerprint:digest('migration'),recipientSha256:digest('recipient'),ageReceiptSha256:digest('age-receipt')};const source={authority,seal:{migrationFingerprint:authority.migrationFingerprint,objectInventory:[]}},input={authority:{reservationAuthority:authority,brokerProfileSha256:String(profile.broker_profile_sha256),runId:'b3000000-0000-4000-8000-000000000001',ageKeyId:digest('key')}};const status={status:'READY',receiptSha256:digest('broker-ready')};const dependencies={profile,profileSha256:digest(profile),source:{read:vi.fn(async()=>source)},brokerInputs:{read:vi.fn(async()=>input)},broker:{status:vi.fn(async()=>status)}};return{dependencies,authority,source,input,status,reader:new ProtectedD3CapturePrerequisites(dependencies as never)};}
  it.each(['valid','source','data','capsule','reservation','broker','seal','ready','missing-receipt','profile'])('requires reverified upstream authorities: %s',async kind=>{const f=prerequisiteFixture();if(kind==='source')f.authority.sourceProfileSha256=digest('foreign');if(kind==='data')f.authority.dataProfileSha256=digest('foreign');if(kind==='capsule')f.authority.capsuleProfileSha256=digest('foreign');if(kind==='reservation')f.authority.reservationProfileSha256=digest('foreign');if(kind==='broker')f.input.authority.brokerProfileSha256=digest('foreign');if(kind==='seal')f.source.seal.migrationFingerprint=digest('foreign');if(kind==='ready')f.status.status='NOT_STARTED';if(kind==='missing-receipt')f.status.receiptSha256='';if(kind==='profile')f.dependencies.profileSha256=digest('foreign');if(kind==='valid')expect(await f.reader.read()).toMatchObject({binding:{runId:f.input.authority.runId,keyId:f.input.authority.ageKeyId}});else await expect(f.reader.read()).rejects.toThrow();});
  it('rejects arbitrary orchestrator paths/fingerprints before any adapter effect',async()=>{const f=await fixture(),identity=await captureIdentity(f.authority),p=prerequisiteFixture();p.authority.recipientSha256=digest(identity.recipient);p.authority.ageReceiptSha256=identity.receiptSha256;p.input.authority.ageKeyId=identity.keyId;const binding=await p.reader.read();f.attempt.bindingSha256=binding.bindingSha256;await expect(f.spool.withAttempt(f.attempt,async lease=>{const credentials={withCredentials:vi.fn()},tools={run:vi.fn()},objects={capture:vi.fn()},packaging={package:vi.fn()},age=vi.fn(),fp={path:'/usr/bin/age' as const,version:'v1.3.2',executableSha256:digest('actual-binary'),imageId:profile.tools_image_id};const adapters=createD3BrokeredCaptureAdapters({authority:f.authority,lease,binding:binding as never,spool:f.spool,credentials,tools,objects,packaging,identity,fingerprint:fp,expectedFingerprint:fp,age});await expect(adapters.captureDatabase('/foreign',new AbortController().signal)).rejects.toThrow();await expect(adapters.captureObjects('/foreign',new AbortController().signal)).rejects.toThrow();await expect(adapters.encrypt!({inputPath:'/foreign',outputPath:'/foreign',executablePath:'/usr/bin/age',expectedExecutableSha256:fp.executableSha256,expectedVersion:fp.version,recipient:identity.recipient})).rejects.toThrow();expect(credentials.withCredentials).not.toHaveBeenCalled();expect(tools.run).not.toHaveBeenCalled();expect(objects.capture).not.toHaveBeenCalled();expect(packaging.package).not.toHaveBeenCalled();expect(age).not.toHaveBeenCalled();})).rejects.toThrow();});
  function transport(body:Buffer,fault='none'):D3CaptureS3Transport {const e='"'+'a'.repeat(32)+'"';let lists=0;return {list:vi.fn(async input=>{lists++;const match=input.Bucket==='archives';return {$metadata:{httpStatusCode:200},Name:input.Bucket,Prefix:input.Prefix??'',MaxKeys:32,KeyCount:match?1:0,IsTruncated:fault==='pagination',...(fault==='pagination'?{NextContinuationToken:'same'}:{}),Contents:match?[{Key:fault==='path'?'backups/foreign':'logs/fixed.json',Size:body.length,ETag:e},...(fault==='duplicate'?[{Key:'logs/fixed.json',Size:body.length,ETag:e}]:[])]:[],...(fault==='drift'&&lists>10?{KeyCount:1,Contents:[{Key:'logs/changed.json',Size:body.length,ETag:e}]}:{})};}),head:vi.fn(async()=>({$metadata:{httpStatusCode:200},ContentLength:body.length,ETag:e})),get:vi.fn(async()=>({$metadata:{httpStatusCode:200},ContentLength:body.length,ETag:e,Body:Readable.from([fault==='body'?Buffer.from('bad'):body])})),close:vi.fn()};}
  it.each(['none','pagination','path','duplicate','drift','body'])('captures every fixed source, detects %s and never exposes a write capability',async fault=>{const f=await fixture(),body=Buffer.from('object-bytes'),t=transport(body,fault),capture=new FixedD3ObjectCapture(profile,f.spool,t);const run=f.spool.withAttempt(f.attempt,lease=>capture.capture(lease,[{bucket:'archives',key:'logs/fixed.json',bytes:body.length,sha256:sha256(body)}]));if(fault==='none'){expect(await run).toHaveLength(1);expect(t.list).toHaveBeenCalledTimes(BACKUP_OBJECT_SOURCES.length*2);expect(t.get).toHaveBeenCalledWith({Bucket:'archives',Key:'logs/fixed.json',IfMatch:expect.any(String)},expect.any(AbortSignal));}else await expect(run).rejects.toThrow();expect(Object.keys(t).sort()).toEqual(['close','get','head','list']);});
  it('decodes deterministic fixed USTAR through the unchanged production extractor with exact600/0/0/0 metadata',async()=>{const hashes:string[]=[],startedAt=new Date(Date.now()-1000).toISOString();for(let i=0;i<2;i++){const f=await fixture();f.attempt.startedAt=startedAt;await f.spool.withAttempt(f.attempt,async lease=>{const body=Buffer.from('-- deterministic SQL\n');await f.spool.write(lease,{kind:'DATABASE'},source(body));const fake={run:async(_lease:unknown,_op:unknown,sink:(s:AsyncIterable<Uint8Array>)=>Promise<unknown>)=>sink(source(tar([{path:d3CaptureDumpName(f.attempt),bytes:body}])))} as unknown as FixedD3CaptureTools;const packaging=new FixedD3CapturePackaging(f.spool,profile,fake),result=await packaging.package(lease,'database');hashes.push(result.sha256);expect((await lstat(f.spool.path(lease,{kind:'PACKAGE',component:'database'}))).mode&0o777).toBe(0o600);expect(await readdir(`${lease.root}/private`)).toEqual(['database-tar']);});}expect(hashes[0]).toBe(hashes[1]);});
  it.each(['mode','uid','mtime','type','checksum','trailing','content'])('rejects tar %s drift',kind=>{const body=Buffer.from('SQL'),b=tar([{path:'dump.sql',bytes:body}]);if(kind==='mode')b.write('0000644\0',100);if(kind==='uid')b.write('0001750\0',108);if(kind==='mtime')b.write('00000000001\0',136);if(kind==='type')b[156]=50;if(kind==='checksum')b[148]=55;if(kind==='trailing')b[b.length-1]=1;if(kind==='content')b[512]=88;if(!['checksum','trailing','content'].includes(kind)){b.fill(32,148,156);b.write([...b.subarray(0,512)].reduce((a,b)=>a+b,0).toString(8).padStart(6,'0')+'\0 ',148,8);}expect(()=>validateD3CaptureTar(b,[{path:'dump.sql',bytes:3,sha256:sha256(body)}])).toThrow();});
  it('never substitutes image identity for the manifest executable pin',()=>{const fp={path:'/usr/bin/age' as const,version:'v1.3.2',executableSha256:digest('actual-age-bytes'),imageId:profile.tools_image_id};expect(assertD3CaptureFingerprint(fp,fp)).toEqual(fp);expect(()=>assertD3CaptureFingerprint({...fp,executableSha256:profile.tools_image_id.slice(7)},fp)).toThrow();});
  it('puts secrets only in a0600 read-only-bound fixed passfile and deletes it only after joined callback',async()=>{const f=await fixture();await protectD3Directory(f.authority,`${f.root}/source/secrets`,true);await publishD3ProtectedBytes(f.authority,`${f.root}/source/secrets/postgres-password`,Buffer.from('a'.repeat(64)+'\n'));const credentials=new ProtectedD3PgCaptureCredentials(f.authority,{verify:async()=>({evidenceSha256:digest('layout')} as never)});await f.spool.withAttempt(f.attempt,lease=>credentials.withCredentials(lease,async()=>{const p=`${lease.root}/private/pgpass`;expect((await lstat(p)).mode&0o777).toBe(0o600);expect(await readFile(p,'utf8')).toBe(`darshan-d2-20261030-postgres:5432:darshan:darshan:${'a'.repeat(64)}\n`);}));});
});
